const upsertAccountHandle = `-- name: UpsertAccountHandle :exec
INSERT INTO account_handles (account_id, username, username_normalized, domain) VALUES ($1, $2, $3, $4)
ON CONFLICT (account_id) DO UPDATE SET
  username = excluded.username,
  username_normalized = excluded.username_normalized,
  domain = excluded.domain
`

type UpsertAccountHandleParams struct {
	AccountID          string
	Username           string
	UsernameNormalized string
	Domain             string
}

func (q *Queries) UpsertAccountHandle(ctx context.Context, arg UpsertAccountHandleParams) error {
	_, err := q.db.Exec(ctx, upsertAccountHandle,
		arg.AccountID,
		arg.Username,
		arg.UsernameNormalized,
		arg.Domain,
	)
	return err
}

